<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Retro Neon Snake</title>
  <style>
    :root {
      --bg-color: #0d0e15;
      --container-bg: #161824;
      --border-color: #2b2e42;
      --accent-cyan: #00f0ff;
      --accent-blue: #0072ff;
      --accent-pink: #ff1744;
      --text-main: #ffffff;
      --text-muted: #767d96;
    }

    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    body {
      background-color: var(--bg-color);
      color: var(--text-main);
      font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, Roboto, Helvetica, Arial, sans-serif;
      display: flex;
      justify-content: center;
      align-items: center;
      min-height: 100vh;
      overflow: hidden;
    }

    .game-container {
      background-color: var(--container-bg);
      border: 2px solid var(--border-color);
      border-radius: 16px;
      padding: 24px;
      box-shadow: 0 20px 50px rgba(0, 0, 0, 0.6);
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 20px;
    }

    .header {
      width: 100%;
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding-bottom: 10px;
      border-bottom: 1px solid var(--border-color);
    }

    h1 {
      font-size: 24px;
      font-weight: 800;
      letter-spacing: 2px;
      background: linear-gradient(45deg, var(--accent-cyan), var(--accent-blue));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
    }

    .score-container {
      font-size: 18px;
      font-weight: 700;
      letter-spacing: 1px;
      color: var(--text-main);
    }

    #score {
      color: var(--accent-cyan);
      font-variant-numeric: tabular-nums;
    }

    #snake {
      width: 400px;
      height: 400px;
      background-color: #0f111a;
      border: 3px solid var(--border-color);
      border-radius: 8px;
      display: block;
      box-shadow: inset 0 0 20px rgba(0, 0, 0, 0.8);
    }

    .controls {
      display: flex;
      gap: 12px;
      width: 100%;
    }

    button {
      flex: 1;
      padding: 12px;
      font-size: 14px;
      font-weight: 700;
      letter-spacing: 1px;
      color: var(--text-main);
      background-color: #202436;
      border: 1px solid var(--border-color);
      border-radius: 8px;
      cursor: pointer;
      transition: all 0.2s ease;
    }

    button:hover {
      background-color: #2b304a;
      border-color: var(--accent-cyan);
      box-shadow: 0 0 10px rgba(0, 240, 255, 0.2);
    }

    button:active {
      transform: scale(0.97);
    }

    #start {
      border-color: #00e676;
    }
    #start:hover {
      background-color: rgba(0, 230, 118, 0.1);
      border-color: #00e676;
      box-shadow: 0 0 10px rgba(0, 230, 118, 0.2);
    }

    #pause {
      border-color: #ffd600;
    }
    #pause:hover {
      background-color: rgba(255, 214, 0, 0.1);
      border-color: #ffd600;
      box-shadow: 0 0 10px rgba(255, 214, 0, 0.2);
    }

    .instructions {
      font-size: 12px;
      color: var(--text-muted);
      text-align: center;
      line-height: 1.5;
    }

    .key {
      background-color: #202436;
      border: 1px solid var(--border-color);
      border-radius: 4px;
      padding: 2px 6px;
      color: var(--accent-cyan);
    }
  </style>
</head>
<body>

  <div class="game-container">
    <div class="header">
      <h1>SNAKE</h1>
      <div class="score-container">SCORE: <span id="score">0</span></div>
    </div>

    <canvas id="snake" width="400" height="400"></canvas>

    <div class="controls">
      <button id="start">START</button>
      <button id="pause">PAUSE</button>
      <button id="reset">RESET</button>
    </div>

    <div class="instructions">
      Use keys <span class="key">▲</span> <span class="key">▼</span> <span class="key">◀</span> <span class="key">▶</span> to change direction.
    </div>
  </div>

  <script>
    (function() {
      const canvas = document.getElementById('snake');
      const ctx = canvas.getContext('2d');
      const scoreElement = document.getElementById('score');

      // Grid definition
      const w = 20;
      const h = 20;
      const cellSize = canvas.width / w; // 400 / 20 = 20px

      // Game state variables
      let snakeBody = [];
      let food = [0, 0];
      let alive = true;
      let gameScore = 0;
      let currentDir = 'right';
      let nextDir = 'right';
      let intervalId = null;
      const TICK_SPEED = 130; // ms

      const dirVectors = {
        'up': [0, -1],
        'down': [0, 1],
        'left': [-1, 0],
        'right': [1, 0]
      };

      const opposites = {
        'up': 'down',
        'down': 'up',
        'left': 'right',
        'right': 'left'
      };

      // Set up random food placement on empty space
      function spawnFood() {
        const emptySpots = [];
        for (let x = 0; x < w; x++) {
          for (let y = 0; y < h; y++) {
            const onSnake = snakeBody.some(seg => seg[0] === x && seg[1] === y);
            if (!onSnake) {
              emptySpots.push([x, y]);
            }
          }
        }
        if (emptySpots.length > 0) {
          const idx = Math.floor(Math.random() * emptySpots.length);
          food = emptySpots[idx];
        }
      }

      // Sync visual UI elements
      function updateUI() {
        scoreElement.textContent = gameScore;
      }

      // Drawing function
      function draw() {
        // Clear canvas
        ctx.fillStyle = '#0f111a';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // Draw grid lines (subtle dark grid)
        ctx.strokeStyle = '#181b28';
        ctx.lineWidth = 1;
        for (let i = 0; i <= w; i++) {
          ctx.beginPath();
          ctx.moveTo(i * cellSize, 0);
          ctx.lineTo(i * cellSize, canvas.height);
          ctx.stroke();
        }
        for (let j = 0; j <= h; j++) {
          ctx.beginPath();
          ctx.moveTo(0, j * cellSize);
          ctx.lineTo(canvas.width, j * cellSize);
          ctx.stroke();
        }

        // Draw food (glowing neon red circle)
        ctx.shadowBlur = 10;
        ctx.shadowColor = 'rgba(255, 23, 68, 0.8)';
        ctx.fillStyle = '#ff1744';
        ctx.beginPath();
        const foodCenterX = food[0] * cellSize + cellSize / 2;
        const foodCenterY = food[1] * cellSize + cellSize / 2;
        ctx.arc(foodCenterX, foodCenterY, cellSize / 2 - 2, 0, 2 * Math.PI);
        ctx.fill();

        // Draw snake body (glowing neon cyan segments)
        ctx.shadowBlur = 8;
        ctx.shadowColor = 'rgba(0, 240, 255, 0.6)';
        const gap = 1;

        snakeBody.forEach((seg, index) => {
          if (index === 0) {
            // Brighter Cyan Head
            ctx.fillStyle = '#00f0ff';
          } else {
            // Blue/Cyan Body
            ctx.fillStyle = '#0072ff';
          }
          ctx.fillRect(
            seg[0] * cellSize + gap,
            seg[1] * cellSize + gap,
            cellSize - gap * 2,
            cellSize - gap * 2
          );
        });

        // Reset shadow for text overlays
        ctx.shadowBlur = 0;

        // Draw Game Over Screen Overlay
        if (!alive) {
          ctx.fillStyle = 'rgba(11, 12, 21, 0.85)';
          ctx.fillRect(0, 0, canvas.width, canvas.height);

          ctx.fillStyle = '#ff1744';
          ctx.font = 'bold 28px "Segoe UI", sans-serif';
          ctx.textAlign = 'center';
          ctx.textBaseline = 'middle';
          ctx.fillText('GAME OVER', canvas.width / 2, canvas.height / 2 - 20);

          ctx.fillStyle = '#ffffff';
          ctx.font = '14px "Segoe UI", sans-serif';
          ctx.fillText('Click RESET to play again', canvas.width / 2, canvas.height / 2 + 20);
        }
      }

      // Single step function
      function tick() {
        if (!alive) return;

        currentDir = nextDir;
        const dirVec = dirVectors[currentDir];
        const head = snakeBody[0];
        const newHead = [head[0] + dirVec[0], head[1] + dirVec[1]];

        // Wall collision check
        if (newHead[0] < 0 || newHead[0] >= w || newHead[1] < 0 || newHead[1] >= h) {
          alive = false;
          draw();
          updateUI();
          return;
        }

        // Self-collision check
        const eating = (newHead[0] === food[0] && newHead[1] === food[1]);
        const bodyToCheck = eating ? snakeBody : snakeBody.slice(0, -1);
        const selfCollide = bodyToCheck.some(seg => seg[0] === newHead[0] && seg[1] === newHead[1]);

        if (selfCollide) {
          alive = false;
          draw();
          updateUI();
          return;
        }

        // Apply movement
        snakeBody.unshift(newHead);
        if (eating) {
          gameScore++;
          spawnFood();
        } else {
          snakeBody.pop();
        }

        draw();
        updateUI();
      }

      // Safe direction changer (ignores 180 degree turns instantly based on exact body shape)
      function setDir(dir) {
        if (!dirVectors[dir]) return;

        let physicalHeading = currentDir;
        if (snakeBody.length >= 2) {
          const dx = snakeBody[0][0] - snakeBody[1][0];
          const dy = snakeBody[0][1] - snakeBody[1][1];
          if (dx === 1 && dy === 0) physicalHeading = 'right';
          else if (dx === -1 && dy === 0) physicalHeading = 'left';
          else if (dx === 0 && dy === 1) physicalHeading = 'down';
          else if (dx === 0 && dy === -1) physicalHeading = 'up';
        }

        if (dir !== opposites[physicalHeading]) {
          nextDir = dir;
        }
      }

      function reset() {
        pauseAuto();
        alive = true;
        gameScore = 0;
        currentDir = 'right';
        nextDir = 'right';

        // Start snake with size 3, heading right
        snakeBody = [
          [10, 10],
          [9, 10],
          [8, 10]
        ];

        spawnFood();
        draw();
        updateUI();
      }

      function setFood(x, y) {
        food = [x, y];
        draw();
      }

      // Automatic timer management
      function startAuto() {
        if (intervalId || !alive) return;
        intervalId = setInterval(tick, TICK_SPEED);
      }

      function pauseAuto() {
        if (intervalId) {
          clearInterval(intervalId);
          intervalId = null;
        }
      }

      // User Keyboard Controls
      window.addEventListener('keydown', (e) => {
        let handled = false;
        switch (e.key) {
          case 'ArrowUp':
            setDir('up');
            handled = true;
            break;
          case 'ArrowDown':
            setDir('down');
            handled = true;
            break;
          case 'ArrowLeft':
            setDir('left');
            handled = true;
            break;
          case 'ArrowRight':
            setDir('right');
            handled = true;
            break;
        }
        if (handled) {
          e.preventDefault();
          // Auto start the run when arrows are pressed
          if (!intervalId && alive) {
            startAuto();
          }
        }
      });

      // UI Button Bindings
      document.getElementById('start').addEventListener('click', startAuto);
      document.getElementById('pause').addEventListener('click', pauseAuto);
      document.getElementById('reset').addEventListener('click', reset);

      // Initialize the Game
      reset();

      // Programmatic API required for grading
      window.game = {
        w,
        h,
        reset,
        tick,
        setDir,
        setFood,
        snake: () => snakeBody.map(p => [p[0], p[1]]),
        food: () => [food[0], food[1]],
        alive: () => alive,
        score: () => gameScore
      };
    })();
  </script>

</body>
</html>
